{
  "verdict": "request_changes",
  "summary": "Candidate code sleeps after the final failed attempt, violating the contract.",
  "findings": [
    {
      "finding_id": "FC001",
      "file": "candidate.py",
      "line_start": 12,
      "line_end": 12,
      "severity": "high",
      "description": "The implementation calls sleep on every TransientError, including the final attempt. The specification requires that no sleep occur after the last failure; the function should re‑raise the TransientError immediately.",
      "evidence": "When attempts=1 and the operation raises TransientError, the code executes sleep(base_delay * 2 ** 0) before raising the error, contrary to the contract which mandates no sleep after the final failure."
    }
  ]
}
